"use client"

import type React from "react"

import { useState } from "react"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import type { Ticket } from "@/hooks/use-tickets"

interface KanbanBoardProps {
  tickets: Ticket[]
  onStatusChange: (ticketId: string, newStatus: Ticket["status"], changedBy: string) => void
  onSelectTicket: (ticketId: string) => void
  userName: string
}

const STATUS_COLUMNS: { id: Ticket["status"]; label: string; color: string }[] = [
  { id: "nuevo", label: "Nuevo", color: "bg-slate-100 border-slate-300" },
  { id: "en_progreso", label: "En Progreso", color: "bg-blue-100 border-blue-300" },
  { id: "revisión", label: "Revisión", color: "bg-yellow-100 border-yellow-300" },
  { id: "aprobado", label: "Aprobado", color: "bg-green-100 border-green-300" },
  { id: "completado", label: "Completado", color: "bg-emerald-100 border-emerald-300" },
  { id: "rechazado", label: "Rechazado", color: "bg-red-100 border-red-300" },
]

const PRIORITY_COLORS: Record<string, string> = {
  baja: "bg-blue-50 text-blue-700 border-blue-200",
  media: "bg-yellow-50 text-yellow-700 border-yellow-200",
  alta: "bg-red-50 text-red-700 border-red-200",
}

export function KanbanBoard({ tickets, onStatusChange, onSelectTicket, userName }: KanbanBoardProps) {
  const [draggedTicket, setDraggedTicket] = useState<string | null>(null)

  const handleDragStart = (e: React.DragEvent, ticketId: string) => {
    setDraggedTicket(ticketId)
    e.dataTransfer.effectAllowed = "move"
  }

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault()
    e.dataTransfer.dropEffect = "move"
  }

  const handleDrop = (e: React.DragEvent, newStatus: Ticket["status"]) => {
    e.preventDefault()
    if (draggedTicket) {
      onStatusChange(draggedTicket, newStatus, userName)
      setDraggedTicket(null)
    }
  }

  return (
    <div className="space-y-4">
      <div>
        <h3 className="text-lg font-semibold text-foreground">Vista Kanban</h3>
        <p className="text-sm text-muted-foreground">Arrastra las tarjetas para cambiar el estado</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-6 gap-4 overflow-x-auto pb-4">
        {STATUS_COLUMNS.map((column) => {
          const columnTickets = tickets.filter((t) => t.status === column.id)

          return (
            <div
              key={column.id}
              onDragOver={handleDragOver}
              onDrop={(e) => handleDrop(e, column.id)}
              className={`flex-shrink-0 w-full lg:w-80 rounded-lg border-2 p-4 min-h-96 ${column.color}`}
            >
              <div className="flex items-center justify-between mb-4">
                <h4 className="font-semibold text-foreground">{column.label}</h4>
                <span className="text-xs font-medium text-muted-foreground bg-background px-2 py-1 rounded">
                  {columnTickets.length}
                </span>
              </div>

              <div className="space-y-3">
                {columnTickets.map((ticket) => (
                  <div
                    key={ticket.id}
                    draggable
                    onDragStart={(e) => handleDragStart(e, ticket.id)}
                    onClick={() => onSelectTicket(ticket.id)}
                    className="bg-white rounded-lg border border-foreground/10 p-3 cursor-move hover:shadow-md transition-all hover:border-primary/30 group"
                  >
                    <div className="flex items-start justify-between gap-2 mb-2">
                      <div className="flex-1">
                        <p className="text-xs font-bold text-primary">{ticket.id}</p>
                        <p className="text-sm font-medium text-foreground line-clamp-2">{ticket.title}</p>
                      </div>
                    </div>

                    <div className="flex items-center gap-2 mb-3">
                      <Badge variant="outline" className={PRIORITY_COLORS[ticket.priority]}>
                        {ticket.priority}
                      </Badge>
                      <Badge variant="secondary" className="text-xs">
                        {ticket.type}
                      </Badge>
                    </div>

                    <div className="flex items-center justify-between text-xs">
                      <span className="text-muted-foreground">{ticket.department}</span>
                      {ticket.assignedTo && (
                        <span className="font-medium text-primary">{ticket.assignedTo.split(" ")[0]}</span>
                      )}
                    </div>

                    {ticket.subtasks.length > 0 && (
                      <div className="mt-2 pt-2 border-t border-foreground/5">
                        <p className="text-xs text-muted-foreground">
                          Subtareas: {ticket.subtasks.filter((s) => s.completed).length}/{ticket.subtasks.length}
                        </p>
                      </div>
                    )}

                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={(e) => {
                        e.stopPropagation()
                        onSelectTicket(ticket.id)
                      }}
                      className="w-full mt-2 text-xs h-7 opacity-0 group-hover:opacity-100 transition-opacity"
                    >
                      Ver Detalles
                    </Button>
                  </div>
                ))}

                {columnTickets.length === 0 && (
                  <div className="text-center py-8 text-muted-foreground text-sm">
                    <p>No hay tickets aquí</p>
                    <p className="text-xs mt-1">Arrastra uno para comenzar</p>
                  </div>
                )}
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )
}
