"use client"

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import type { Ticket } from "@/hooks/use-tickets"

interface DependenciesManagerProps {
  ticket: Ticket
  allTickets: Ticket[]
  onSelectTicket: (ticketId: string) => void
}

export function DependenciesManager({ ticket, allTickets, onSelectTicket }: DependenciesManagerProps) {
  const relatedTickets = allTickets.filter((t) => ticket.dependencies.includes(t.id))
  const dependingTickets = allTickets.filter((t) => t.dependencies.includes(ticket.id))

  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-base">Dependencias y Relaciones</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Depende de */}
        <div>
          <h4 className="font-medium text-sm mb-3">Depende de</h4>
          {relatedTickets.length === 0 ? (
            <p className="text-xs text-muted-foreground">No tiene dependencias</p>
          ) : (
            <div className="space-y-2">
              {relatedTickets.map((t) => (
                <div
                  key={t.id}
                  className="flex items-start justify-between p-2 rounded border border-foreground/10 hover:bg-muted/50"
                >
                  <div className="flex-1">
                    <p className="text-xs font-bold text-primary">{t.id}</p>
                    <p className="text-sm text-foreground line-clamp-1">{t.title}</p>
                  </div>
                  <Button variant="ghost" size="sm" onClick={() => onSelectTicket(t.id)} className="text-xs h-7">
                    Ver
                  </Button>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Bloqueadores */}
        <div className="border-t pt-4">
          <h4 className="font-medium text-sm mb-3">Bloqueados por</h4>
          {dependingTickets.length === 0 ? (
            <p className="text-xs text-muted-foreground">No hay bloqueos</p>
          ) : (
            <div className="space-y-2">
              {dependingTickets.map((t) => (
                <div
                  key={t.id}
                  className="flex items-start justify-between p-2 rounded border border-red-200 bg-red-50 hover:bg-red-100"
                >
                  <div className="flex-1">
                    <p className="text-xs font-bold text-red-700">{t.id}</p>
                    <p className="text-sm text-red-900 line-clamp-1">{t.title}</p>
                  </div>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => onSelectTicket(t.id)}
                    className="text-xs h-7 text-red-700"
                  >
                    Ver
                  </Button>
                </div>
              ))}
            </div>
          )}
        </div>
      </CardContent>
    </Card>
  )
}
