"use client"

import { useState, useCallback } from "react"
import { Card, CardContent } from "@/components/ui/card"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { useTickets } from "@/hooks/use-tickets"
import { KanbanBoard } from "@/components/kanban-board"
import { AdvancedFilters } from "@/components/advanced-filters"
import { TicketDetailView } from "@/components/ticket-detail-view"
import { AnalystTicketCard } from "@/components/analyst-ticket-card"
import { DashboardOverview } from "@/components/dashboard-overview"

export function AnalystDashboard() {
  const { tickets, updateTicket, addComment, addSubtask } = useTickets()
  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null)
  const [filteredTickets, setFilteredTickets] = useState<typeof tickets>(tickets)
  const [viewMode, setViewMode] = useState<"kanban" | "table">("kanban")

  const selectedTicket = selectedTicketId ? tickets.find((t) => t.id === selectedTicketId) : null

  const handleUpdateSubtask = useCallback(
    (ticketId: string, subtaskId: string, completed: boolean) => {
      const ticket = tickets.find((t) => t.id === ticketId)
      if (ticket) {
        const updatedSubtasks = ticket.subtasks.map((s) => (s.id === subtaskId ? { ...s, completed } : s))
        updateTicket(ticketId, { subtasks: updatedSubtasks }, "Analista")
      }
    },
    [tickets, updateTicket],
  )

  return (
    <div className="space-y-8">
      {/* Header */}
      <div>
        <h2 className="text-3xl font-bold text-foreground">Panel de Analista</h2>
        <p className="text-muted-foreground mt-1">
          Gestiona todos los requerimientos de análisis con trazabilidad completa
        </p>
      </div>

      {/* Dashboard Overview */}
      <DashboardOverview tickets={filteredTickets} />

      {/* Stats */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-6 gap-4">
        <Card>
          <CardContent className="pt-6">
            <p className="text-xs text-muted-foreground">Total</p>
            <p className="text-2xl font-bold text-primary">{filteredTickets.length}</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <p className="text-xs text-muted-foreground">Nuevo</p>
            <p className="text-2xl font-bold text-slate-600">{newTickets.length}</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <p className="text-xs text-muted-foreground">En Progreso</p>
            <p className="text-2xl font-bold text-blue-600">{inProgressTickets.length}</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <p className="text-xs text-muted-foreground">Revisión</p>
            <p className="text-2xl font-bold text-yellow-600">{reviewTickets.length}</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <p className="text-xs text-muted-foreground">Aprobado</p>
            <p className="text-2xl font-bold text-green-600">{approvedTickets.length}</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <p className="text-xs text-muted-foreground">Completado</p>
            <p className="text-2xl font-bold text-emerald-600">{completedTickets.length}</p>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <AdvancedFilters tickets={tickets} onFiltersChange={setFilteredTickets} />

      {/* View Modes */}
      <Tabs value={viewMode} onValueChange={(value) => setViewMode(value as "kanban" | "table")} className="w-full">
        <TabsList className="grid w-full grid-cols-2 bg-muted mb-6">
          <TabsTrigger value="kanban">Vista Kanban</TabsTrigger>
          <TabsTrigger value="table">Vista Tabla</TabsTrigger>
        </TabsList>

        {/* Kanban View */}
        <TabsContent value="kanban" className="space-y-4">
          <KanbanBoard
            tickets={filteredTickets}
            onStatusChange={(ticketId, newStatus, changedBy) => {
              updateTicket(ticketId, { status: newStatus }, changedBy)
            }}
            onSelectTicket={setSelectedTicketId}
            userName="Analista"
          />
        </TabsContent>

        {/* Table View */}
        <TabsContent value="table" className="space-y-4">
          <div className="space-y-4">
            {filteredTickets.length === 0 ? (
              <Card>
                <CardContent className="pt-8 text-center">
                  <p className="text-muted-foreground">No hay tickets con estos filtros</p>
                </CardContent>
              </Card>
            ) : (
              filteredTickets.map((ticket) => (
                <AnalystTicketCard
                  key={ticket.id}
                  ticket={ticket}
                  onUpdate={(updatedTicket) => updateTicket(ticket.id, updatedTicket, "Analista")}
                  isSelected={selectedTicketId === ticket.id}
                  onSelect={() => setSelectedTicketId(ticket.id)}
                />
              ))
            )}
          </div>
        </TabsContent>
      </Tabs>

      {/* Detailed View */}
      {selectedTicket && (
        <div className="border-t pt-6">
          <TicketDetailView
            ticket={selectedTicket}
            allTickets={filteredTickets}
            onStatusChange={(status) => updateTicket(selectedTicket.id, { status }, "Analista")}
            onAssignChange={(assignee) => updateTicket(selectedTicket.id, { assignedTo: assignee || null }, "Analista")}
            onAddComment={(text, mentions) => addComment(selectedTicket.id, "Analista", text, mentions)}
            onAddSubtask={(subtask) => addSubtask(selectedTicket.id, subtask)}
            onUpdateSubtask={(subtaskId, completed) => handleUpdateSubtask(selectedTicket.id, subtaskId, completed)}
            userName="Analista"
          />
        </div>
      )}
    </div>
  )
}

const newTickets = (tickets: any) => tickets.filter((t: any) => t.status === "nuevo")
const inProgressTickets = (tickets: any) => tickets.filter((t: any) => t.status === "en_progreso")
const reviewTickets = (tickets: any) => tickets.filter((t: any) => t.status === "revisión")
const approvedTickets = (tickets: any) => tickets.filter((t: any) => t.status === "aprobado")
const completedTickets = (tickets: any) => tickets.filter((t: any) => t.status === "completado")
const rejectedTickets = (tickets: any) => tickets.filter((t: any) => t.status === "rechazado")
