"use client"

import { useState } from "react"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { TicketForm } from "@/components/ticket-form"
import { TicketCard } from "@/components/ticket-card"
import { useTickets } from "@/hooks/use-tickets"

// Definimos la interfaz aquí o impórtala de tu archivo de tipos
interface Ticket {
  id: string
  title: string
  description: string
  priority: string
  status: string
  type: string
  department: string
  area: string
  impact: string
  createdAt: string
  requesterId: string
  requesterEmail: string
  requestedBy: string
  assignedTo: string | null
  labels: string[]
  dependencies: string[]
  subtasks: any[]
  comments: any[]
  auditLog: any[]
  changeHistory: any[]
}

interface RequesterDashboardProps {
  userName: string
}

export function RequesterDashboard({ userName }: RequesterDashboardProps) {
  const [showForm, setShowForm] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const { tickets, addTicket } = useTickets()

  // BLINDAJE: Protección contra userName undefined para evitar error de toLowerCase
  const safeUserName = userName || ""

  // FILTRO CORRECTO: Usamos el safeUserName para filtrar los tickets del usuario
  const userTickets = (tickets || []).filter((t) =>
    t.requesterEmail?.toLowerCase() === safeUserName.toLowerCase()
  );

  // Mapeo de áreas oficial para Soltrak
  const AREA_MAP: Record<string, string> = {
    "mejora.continua@soltrak.com.pe": "Mejora Continua",
    "logistica@soltrak.com.pe": "Logística",
    "planeamiento@soltrak.com.pe": "Planeamiento y Demanda",
    "marketing@soltrak.com.pe": "Marketing",
    "creditos@soltrak.com.pe": "Créditos y Cobranzas",
  };

  const handleSubmit = async (formData: any) => {
  setIsSubmitting(true)

  const safeUserName = userName || ""
  const emailKey = safeUserName.toLowerCase().trim()
  const areaName = AREA_MAP[emailKey] || "Área General"
  const now = new Date().toISOString()

  // Solo enviamos los datos base, el Hook pondrá el ID STRKDT-XXXX
  const baseData = {
    title: formData.title,
    description: formData.description,
    priority: formData.priority,
    status: "nuevo",
    requesterId: areaName,
    requesterEmail: emailKey,
    requestedBy: areaName,
    createdAt: now,
    comments: [],
    auditLog: [{ 
      id: `log-${Date.now()}`, 
      action: "created", 
      changedBy: areaName, 
      changedAt: now 
    }],
    changeHistory: [{ 
      date: now, 
      user: areaName, 
      summary: "Creó el requerimiento" 
    }],
    subtasks: [],
    assignedTo: null,
    // Otros campos necesarios por tu interfaz
    type: "mejora",
    department: areaName,
    area: areaName,
    impact: "medio",
    labels: [],
    dependencies: []
  }

  await addTicket(baseData)
  
  setShowForm(false)
  setIsSubmitting(false)
}

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-3xl font-bold text-slate-900 tracking-tight">Mis Solicitudes</h2>
          <p className="text-muted-foreground mt-1 font-medium">
            Área: <span className="text-[#b31942] uppercase">{AREA_MAP[safeUserName.toLowerCase()] || "Usuario Piloto"}</span>
          </p>
        </div>
        <Button
          onClick={() => setShowForm(!showForm)}
          disabled={isSubmitting}
          className="bg-[#b31942] hover:bg-[#8e1435] text-white gap-2 shadow-md transition-transform active:scale-95"
        >
          <span className="text-lg font-bold">+</span>
          {showForm ? "Cerrar Formulario" : "Nuevo Requerimiento"}
        </Button>
      </div>

      {/* Formulario con estado de carga */}
      {showForm && (
        <Card className="border-[#b31942]/20 shadow-xl animate-in fade-in zoom-in duration-200">
          <CardHeader>
            <CardTitle>Crear Nuevo Requerimiento</CardTitle>
            <CardDescription>Detalla tu solicitud para que el equipo de Data pueda procesarla</CardDescription>
          </CardHeader>
          <CardContent className={isSubmitting ? "opacity-50 pointer-events-none" : ""}>
            <TicketForm
              onSubmit={handleSubmit}
              onCancel={() => setShowForm(false)}
              userEmail={safeUserName}
            />
          </CardContent>
        </Card>
      )}

      {/* Stats Cards (Manteniendo tu diseño original) */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card className="border-slate-100 shadow-sm">
          <CardHeader className="pb-3">
            <CardTitle className="text-sm font-semibold text-slate-500 uppercase">Total</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-3xl font-bold text-[#b31942]">{userTickets.length}</p>
          </CardContent>
        </Card>
        <Card className="border-slate-100 shadow-sm">
          <CardHeader className="pb-3">
            <CardTitle className="text-sm font-semibold text-slate-500 uppercase">Nuevo</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-3xl font-bold text-blue-500">
              {userTickets.filter((t) => t.status === "nuevo").length}
            </p>
          </CardContent>
        </Card>
        <Card className="border-slate-100 shadow-sm">
          <CardHeader className="pb-3">
            <CardTitle className="text-sm font-semibold text-slate-500 uppercase">En Progreso</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-3xl font-bold text-amber-500">
              {userTickets.filter((t) => t.status === "en_progreso").length}
            </p>
          </CardContent>
        </Card>
        <Card className="border-slate-100 shadow-sm">
          <CardHeader className="pb-3">
            <CardTitle className="text-sm font-semibold text-slate-500 uppercase">Completado</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-3xl font-bold text-emerald-600">
              {userTickets.filter((t) => t.status === "completado").length}
            </p>
          </CardContent>
        </Card>
      </div>

      {/* Tickets List */}
      <div className="space-y-4">
        <h3 className="text-lg font-bold text-slate-800 border-b pb-2">Listado de Requerimientos</h3>
        {userTickets.length === 0 ? (
          <Card className="bg-slate-50/50 border-dashed border-2">
            <CardContent className="pt-12 pb-12 text-center">
              <p className="text-slate-500 font-medium">No tienes requerimientos activos</p>
              <p className="text-sm text-slate-400 mt-1">Usa el botón superior para enviar tu primera solicitud al equipo de Analytics</p>
            </CardContent>
          </Card>
        ) : (
          <div className="grid gap-4">
            {userTickets.map((ticket) => (
              <TicketCard key={ticket.id} ticket={ticket} />
            ))}
          </div>
        )}
      </div>
    </div>
  )
}
