"use client"

import { Badge } from "@/components/ui/badge"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Separator } from "@/components/ui/separator"
import { formatDistanceToNow } from "date-fns" // O tu lib de fechas
import { es } from "date-fns/locale"

export function TicketCard({ ticket, isExpanded, onExpand }: any) {
  return (
    <Card 
      className={`transition-all duration-300 cursor-pointer ${isExpanded ? 'ring-2 ring-[#b31942] shadow-xl' : 'hover:border-slate-300'}`}
      onClick={onExpand}
    >
      <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
        <div className="flex flex-col gap-1">
          <CardTitle className="text-lg font-bold">{ticket.title}</CardTitle>
          <span className="text-xs text-slate-400">ID: {ticket.id} • hace {formatDistanceToNow(new Date(ticket.createdAt), { locale: es })}</span>
        </div>
        <div className="flex gap-2">
          <Badge variant="outline" className={ticket.priority === 'alta' ? 'bg-red-50 text-red-700 border-red-200' : 'bg-amber-50 text-amber-700 border-amber-200'}>
            {ticket.priority.toUpperCase()}
          </Badge>
          <Badge className="bg-slate-100 text-slate-700 border-slate-200 capitalize">
            {ticket.status.replace('_', ' ')}
          </Badge>
        </div>
      </CardHeader>

      {/* CONTENIDO DETALLADO (Solo visible si está expandido) */}
      {isExpanded && (
        <CardContent className="pt-4 animate-in fade-in slide-in-from-top-2 duration-300">
          <Separator className="mb-4" />
          
          <div className="grid md:grid-cols-2 gap-6">
            {/* Columna 1: Especificaciones */}
            <div className="space-y-4">
              <div>
                <h4 className="text-sm font-bold text-[#b31942] uppercase tracking-wider mb-2">Descripción Detallada</h4>
                <p className="text-sm text-slate-600 bg-slate-50 p-3 rounded-lg border border-slate-100 italic">
                  "{ticket.description}"
                </p>
              </div>

              <div>
                <h4 className="text-sm font-bold text-slate-700 mb-2">Progreso del Requerimiento</h4>
                <div className="w-full bg-slate-100 rounded-full h-2.5">
                  <div 
                    className="bg-[#b31942] h-2.5 rounded-full transition-all duration-500" 
                    style={{ width: ticket.status === 'completado' ? '100%' : ticket.status === 'en_progreso' ? '50%' : '10%' }}
                  ></div>
                </div>
                <span className="text-[10px] text-slate-400 mt-1 block">
                  Estado actual: {ticket.status === 'nuevo' ? 'Esperando asignación' : 'Analista trabajando'}
                </span>
              </div>
            </div>

            {/* Columna 2: Historial y Comentarios */}
            <div className="space-y-4">
              <div>
                <h4 className="text-sm font-bold text-slate-700 mb-2">Últimos Comentarios ({ticket.comments?.length || 0})</h4>
                <div className="space-y-2 max-h-32 overflow-y-auto pr-2">
                  {ticket.comments?.length > 0 ? (
                    ticket.comments.map((c: any, i: number) => (
                      <div key={i} className="text-xs p-2 bg-blue-50 border border-blue-100 rounded text-blue-800">
                        <span className="font-bold">{c.author}:</span> {c.text}
                      </div>
                    ))
                  ) : (
                    <p className="text-xs text-slate-400 italic">No hay comentarios técnicos aún.</p>
                  )}
                </div>
              </div>

              <div>
                <h4 className="text-sm font-bold text-slate-700 mb-2">Trazabilidad (Auditoría)</h4>
                <div className="border-l-2 border-slate-100 ml-2 pl-4 space-y-3">
                  {ticket.auditLog?.slice(0, 2).map((log: any, i: number) => (
                    <div key={i} className="relative">
                      <div className="absolute -left-[21px] top-1 w-3 h-3 rounded-full bg-slate-200 border-2 border-white" />
                      <p className="text-[11px] font-medium text-slate-600">{log.action === 'created' ? 'Ticket Creado' : log.field}</p>
                      <p className="text-[9px] text-slate-400">{formatDistanceToNow(new Date(log.changedAt), { locale: es })} por {log.changedBy}</p>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </CardContent>
      )}
    </Card>
  )
}
