"use client"

import { useState } from "react"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Textarea } from "@/components/ui/textarea"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { SubtaskManager } from "@/components/subtask-manager"
import { DependenciesManager } from "@/components/dependencies-manager"
import { ApprovalWorkflow } from "@/components/approval-workflow"
import { SLATracker } from "@/components/sla-tracker"
import type { Ticket } from "@/hooks/use-tickets"

interface TicketDetailViewProps {
  ticket: Ticket
  allTickets?: Ticket[]
  onStatusChange: (status: Ticket["status"]) => void
  onAssignChange: (assignee: string) => void
  onAddComment: (text: string, mentions: string[]) => void
  onAddSubtask?: (subtask: any) => void
  onUpdateSubtask?: (subtaskId: string, completed: boolean) => void
  userName: string
}

const statusColors: Record<string, string> = {
  nuevo: "bg-slate-100 text-slate-800",
  en_progreso: "bg-blue-100 text-blue-800",
  revisión: "bg-yellow-100 text-yellow-800",
  aprobado: "bg-green-100 text-green-800",
  completado: "bg-emerald-100 text-emerald-800",
  rechazado: "bg-red-100 text-red-800",
}

const priorityColors: Record<string, string> = {
  baja: "bg-blue-50 text-blue-700 border-blue-200",
  media: "bg-yellow-50 text-yellow-700 border-yellow-200",
  alta: "bg-red-50 text-red-700 border-red-200",
}

export function TicketDetailView({
  ticket,
  allTickets = [],
  onStatusChange,
  onAssignChange,
  onAddComment,
  onAddSubtask,
  onUpdateSubtask,
  userName,
}: TicketDetailViewProps) {
  const [comment, setComment] = useState("")
  const [expandedAudit, setExpandedAudit] = useState<string | null>(null)

  const handleAddComment = () => {
    if (comment.trim()) {
      const mentions = comment.match(/@(\w+)/g)?.map((m) => m.slice(1)) || []
      onAddComment(comment, mentions)
      setComment("")
    }
  }

  return (
    <div className="space-y-6 max-w-6xl mx-auto">
      {/* Header */}
      <div className="space-y-4">
        <div className="flex items-start justify-between">
          <div>
            <p className="text-sm font-bold text-primary uppercase mb-2">{ticket.id}</p>
            <h1 className="text-3xl font-bold text-foreground">{ticket.title}</h1>
          </div>
          <Badge className={statusColors[ticket.status]}>{ticket.status}</Badge>
        </div>

        <p className="text-muted-foreground">{ticket.description}</p>
      </div>

      {/* Main Details */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left Column - Main Info */}
        <div className="lg:col-span-2 space-y-6">
          {/* Status and Metadata */}
          <Card>
            <CardHeader>
              <CardTitle className="text-base">Información Principal</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <p className="text-sm text-muted-foreground">Prioridad</p>
                  <Badge className={priorityColors[ticket.priority]} variant="outline">
                    {ticket.priority}
                  </Badge>
                </div>
                <div>
                  <p className="text-sm text-muted-foreground">Tipo</p>
                  <Badge variant="secondary">{ticket.type}</Badge>
                </div>
                <div>
                  <p className="text-sm text-muted-foreground">Departamento</p>
                  <p className="font-medium">{ticket.department}</p>
                </div>
                <div>
                  <p className="text-sm text-muted-foreground">Área</p>
                  <p className="font-medium">{ticket.area}</p>
                </div>
                <div>
                  <p className="text-sm text-muted-foreground">Impacto</p>
                  <Badge variant="outline">{ticket.impact}</Badge>
                </div>
                <div>
                  <p className="text-sm text-muted-foreground">Horas Estimadas</p>
                  <p className="font-medium">{ticket.estimatedHours || "N/A"}</p>
                </div>
              </div>

              {ticket.labels.length > 0 && (
                <div>
                  <p className="text-sm text-muted-foreground mb-2">Etiquetas</p>
                  <div className="flex flex-wrap gap-2">
                    {ticket.labels.map((label) => (
                      <Badge key={label} variant="outline">
                        {label}
                      </Badge>
                    ))}
                  </div>
                </div>
              )}
            </CardContent>
          </Card>

          {/* Subtasks */}
          {ticket.subtasks.length > 0 && (
            <Card>
              <CardHeader>
                <CardTitle className="text-base">Subtareas</CardTitle>
              </CardHeader>
              <CardContent className="space-y-2">
                {ticket.subtasks.map((subtask) => (
                  <div key={subtask.id} className="flex items-start gap-3 p-2 rounded hover:bg-muted">
                    <input type="checkbox" checked={subtask.completed} readOnly className="mt-1" />
                    <div className="flex-1">
                      <p className={subtask.completed ? "line-through text-muted-foreground" : "text-foreground"}>
                        {subtask.title}
                      </p>
                      {subtask.assignedTo && (
                        <p className="text-xs text-muted-foreground">Asignado a: {subtask.assignedTo}</p>
                      )}
                    </div>
                  </div>
                ))}
              </CardContent>
            </Card>
          )}

          {/* Subtask Manager */}
          {onAddSubtask && onUpdateSubtask && (
            <SubtaskManager ticket={ticket} onAddSubtask={onAddSubtask} onUpdateSubtask={onUpdateSubtask} />
          )}

          {/* Comentarios */}
          <Card>
            <CardHeader>
              <CardTitle className="text-base">Comentarios</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="space-y-3 max-h-80 overflow-y-auto">
                {ticket.comments.map((c) => (
                  <div key={c.id} className="border-l-2 border-primary/20 pl-3 py-2">
                    <div className="flex items-center justify-between mb-1">
                      <p className="font-medium text-sm">{c.author}</p>
                      <p className="text-xs text-muted-foreground">
                        {new Date(c.createdAt).toLocaleDateString("es-ES", {
                          month: "short",
                          day: "numeric",
                          hour: "2-digit",
                          minute: "2-digit",
                        })}
                      </p>
                    </div>
                    <p className="text-sm text-foreground">{c.text}</p>
                  </div>
                ))}
              </div>

              <div className="space-y-2 border-t pt-4">
                <Textarea
                  placeholder="Escribe un comentario... Usa @nombre para mencionar"
                  value={comment}
                  onChange={(e) => setComment(e.target.value)}
                  rows={3}
                />
                <Button
                  onClick={handleAddComment}
                  className="bg-primary hover:bg-primary/90"
                  disabled={!comment.trim()}
                >
                  Agregar Comentario
                </Button>
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Right Column - Assignments and Status */}
        <div className="space-y-6">
          {/* Assignment */}
          <Card>
            <CardHeader>
              <CardTitle className="text-base">Asignación</CardTitle>
            </CardHeader>
            <CardContent className="space-y-3">
              <div>
                <p className="text-sm text-muted-foreground mb-2">Asignado a</p>
                <Select value={ticket.assignedTo || "default"} onValueChange={onAssignChange}>
                  <SelectTrigger>
                    <SelectValue placeholder="Seleccionar analista" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="default">Sin asignar</SelectItem>
                    <SelectItem value="María García">María García</SelectItem>
                    <SelectItem value="Carlos López">Carlos López</SelectItem>
                    <SelectItem value="Ana Martínez">Ana Martínez</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              {ticket.assignedAt && (
                <div className="text-xs">
                  <p className="text-muted-foreground">Asignado por: {ticket.assignedBy}</p>
                  <p className="text-muted-foreground">{new Date(ticket.assignedAt).toLocaleDateString("es-ES")}</p>
                </div>
              )}
            </CardContent>
          </Card>

          {/* Status Change */}
          <Card>
            <CardHeader>
              <CardTitle className="text-base">Cambiar Estado</CardTitle>
            </CardHeader>
            <CardContent>
              <Select value={ticket.status} onValueChange={(value) => onStatusChange(value as Ticket["status"])}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="nuevo">Nuevo</SelectItem>
                  <SelectItem value="en_progreso">En Progreso</SelectItem>
                  <SelectItem value="revisión">Revisión</SelectItem>
                  <SelectItem value="aprobado">Aprobado</SelectItem>
                  <SelectItem value="completado">Completado</SelectItem>
                  <SelectItem value="rechazado">Rechazado</SelectItem>
                </SelectContent>
              </Select>
            </CardContent>
          </Card>

          {/* SLA Tracker */}
          <SLATracker ticket={ticket} />

          {/* Approval Workflow */}
          <ApprovalWorkflow ticket={ticket} onStatusChange={(status) => onStatusChange(status)} userName={userName} />

          {/* Dependencies Manager */}
          {allTickets.length > 0 && (
            <DependenciesManager
              ticket={ticket}
              allTickets={allTickets}
              onSelectTicket={(ticketId) => {
                // Handle ticket selection
              }}
            />
          )}

          {/* Dates */}
          <Card>
            <CardHeader>
              <CardTitle className="text-base">Fechas</CardTitle>
            </CardHeader>
            <CardContent className="text-xs space-y-2">
              <div>
                <p className="text-muted-foreground">Creado</p>
                <p className="font-medium">{new Date(ticket.createdAt).toLocaleDateString("es-ES")}</p>
              </div>
              {ticket.dueDate && (
                <div>
                  <p className="text-muted-foreground">Vencimiento</p>
                  <p className="font-medium">{new Date(ticket.dueDate).toLocaleDateString("es-ES")}</p>
                </div>
              )}
              {ticket.completedAt && (
                <div>
                  <p className="text-muted-foreground">Completado</p>
                  <p className="font-medium">{new Date(ticket.completedAt).toLocaleDateString("es-ES")}</p>
                </div>
              )}
            </CardContent>
          </Card>
        </div>
      </div>

      {/* Audit Trail */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base">Historial de Cambios y Auditoría</CardTitle>
          <CardDescription>Registro completo de todas las modificaciones realizadas en este ticket</CardDescription>
        </CardHeader>
        <CardContent>
          <Tabs defaultValue="timeline" className="w-full">
            <TabsList className="grid w-full grid-cols-2">
              <TabsTrigger value="timeline">Timeline</TabsTrigger>
              <TabsTrigger value="audit">Log de Auditoría</TabsTrigger>
            </TabsList>

            <TabsContent value="timeline" className="space-y-4 mt-4">
              {ticket.changeHistory.map((entry, idx) => (
                <div key={idx} className="flex gap-4 pb-4 border-b last:border-0 last:pb-0">
                  <div className="flex flex-col items-center">
                    <div className="w-3 h-3 rounded-full bg-primary mt-1" />
                    {idx < ticket.changeHistory.length - 1 && <div className="w-0.5 h-12 bg-primary/20 mt-2" />}
                  </div>
                  <div className="flex-1 pt-0.5">
                    <p className="font-medium text-sm">{entry.user}</p>
                    <p className="text-sm text-foreground">{entry.summary}</p>
                    <p className="text-xs text-muted-foreground mt-1">
                      {new Date(entry.date).toLocaleDateString("es-ES", {
                        month: "long",
                        day: "numeric",
                        year: "numeric",
                        hour: "2-digit",
                        minute: "2-digit",
                      })}
                    </p>
                  </div>
                </div>
              ))}
            </TabsContent>

            <TabsContent value="audit" className="space-y-3 mt-4">
              {ticket.auditLog.reverse().map((log) => (
                <div
                  key={log.id}
                  className="border rounded-lg p-3 hover:bg-muted/50 cursor-pointer transition-colors"
                  onClick={() => setExpandedAudit(expandedAudit === log.id ? null : log.id)}
                >
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <p className="font-medium text-sm">
                        {log.changedBy} - {log.action}
                      </p>
                      <p className="text-xs text-muted-foreground">{log.field}</p>
                    </div>
                    <p className="text-xs text-muted-foreground">
                      {new Date(log.changedAt).toLocaleDateString("es-ES", {
                        month: "short",
                        day: "numeric",
                        hour: "2-digit",
                        minute: "2-digit",
                      })}
                    </p>
                  </div>

                  {expandedAudit === log.id && (
                    <div className="mt-3 pt-3 border-t space-y-2 text-xs">
                      <div>
                        <p className="text-muted-foreground">Valor anterior:</p>
                        <p className="font-mono bg-muted p-2 rounded text-foreground">{log.oldValue || "N/A"}</p>
                      </div>
                      <div>
                        <p className="text-muted-foreground">Nuevo valor:</p>
                        <p className="font-mono bg-muted p-2 rounded text-foreground">{log.newValue || "N/A"}</p>
                      </div>
                    </div>
                  )}
                </div>
              ))}
            </TabsContent>
          </Tabs>
        </CardContent>
      </Card>
    </div>
  )
}
